package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonStore;
import net.officefloor.hq.app.rate.RateStore;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.hq.app.setting.SettingStore;
import net.officefloor.hq.app.sheet.SheetStore;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Works out the move a status change makes. A clerk settling an OPEN claim whose due is above the
 *  sheet's clerk limit sends it to PENDING instead. A claim whose due is n/a is within any limit; a
 *  sheet with no limit, and a steward, settle anything. Only a steward reviews a PENDING claim, and
 *  only a review moves it to SETTLED or back to OPEN; a review of a claim that is not PENDING is refused.
 *  Before the limit is considered, settling or approving a claim with no proofs whose due is above the
 *  proof threshold is refused (see {@link CheckProofs}), so it never goes to PENDING. */
public class CheckClerkLimit {
    public void check(@Val StatusInput input, @Val Claim claim, RoleStore roles, SettingStore settings,
            PersonStore people, RateStore rates, SheetStore sheets, ClaimStore claims, Out<StatusMove> move)
            throws InvalidSheetException {
        ClaimStatus from = claim.getStatus();
        boolean steward = roles.find(claim.getSheetId(), input.user()) == Role.STEWARD;
        if (input.review()) {
            if (from != ClaimStatus.PENDING) {
                throw new InvalidSheetException("Only a PENDING claim can be approved or rejected");
            }
            if (!steward) {
                throw new InvalidSheetException("Only a steward can approve or reject a claim");
            }
            CheckProofs.refuseUnproved(input, claim, settings, people, rates, sheets, claims);
            move.set(new StatusMove(from, input.status()));
            return;
        }
        if (from == ClaimStatus.PENDING && input.status() != ClaimStatus.VOID) {
            throw new InvalidSheetException("A PENDING claim waits for a steward to approve or reject it");
        }
        CheckProofs.refuseUnproved(input, claim, settings, people, rates, sheets, claims);
        move.set(new StatusMove(from, overLimit(input, claim, steward, settings, people, rates, sheets, claims)
                ? ClaimStatus.PENDING : input.status()));
    }

    private static boolean overLimit(StatusInput input, Claim claim, boolean steward, SettingStore settings,
            PersonStore people, RateStore rates, SheetStore sheets, ClaimStore claims) {
        if (input.status() != ClaimStatus.SETTLED || claim.getStatus() != ClaimStatus.OPEN || steward) {
            return false;
        }
        BigDecimal limit = settings.clerkLimit(claim.getSheetId());
        if (limit == null) {
            return false;
        }
        Person person = people.find(claim.getSheetId(), claim.getPersonId());
        BigDecimal pct = person == null ? null : rates.find(claim.getSheetId(), person.gradeOn(claim.getDate()), claim.getDate());
        BigDecimal due = Lateness.of(claim.getSheetId(), settings, sheets, claims).due(claim, pct);
        return due != null && due.compareTo(limit) > 0;
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateStatus {
    public void validate(@RequestBody StatusRequest request, Out<StatusInput> body) throws InvalidSheetException {
        String status = request == null || request.status() == null ? "" : request.status().trim();
        ClaimStatus to;
        try {
            to = ClaimStatus.valueOf(status);
        } catch (IllegalArgumentException e) {
            throw new InvalidSheetException("Not a claim status: " + status);
        }
        boolean review = Boolean.TRUE.equals(request.review());
        String reason = request.reason() == null ? "" : request.reason().trim();
        if (review && to != ClaimStatus.SETTLED && to != ClaimStatus.OPEN) {
            throw new InvalidSheetException("A review approves or rejects a claim");
        }
        if (review && to == ClaimStatus.OPEN && reason.isEmpty()) {
            throw new InvalidSheetException("A rejection needs a reason");
        }
        body.set(new StatusInput(to, request.user(), review, reason));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonStore;
import net.officefloor.hq.app.person.Retirement;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Refuses a claim's move unless a steward moves a DRAFT, OPEN or PENDING claim that is not a
 *  correction to another person on the sheet, who is not retired from before the claim's date. */
public class CheckReassign {
    public void check(@Val ReassignInput input, @Val Claim claim, RoleStore roles, PersonStore people,
            Out<Reassignment> reassignment) throws InvalidSheetException {
        if (roles.find(claim.getSheetId(), input.user()) != Role.STEWARD) {
            throw new InvalidSheetException("Only a steward can move a claim");
        }
        if (!claim.getStatus().canMove()) {
            throw new InvalidSheetException("A " + claim.getStatus() + " claim cannot move");
        }
        if (claim.isCorrection()) {
            throw new InvalidSheetException("A correction stays with the claim it corrects");
        }
        Person from = people.find(claim.getSheetId(), claim.getPersonId());
        Person to = people.find(claim.getSheetId(), input.to());
        if (to == null) {
            throw new InvalidSheetException("No such person: " + input.to());
        }
        if (to.getId() == claim.getPersonId()) {
            throw new InvalidSheetException("The claim is already " + to.getName() + "'s");
        }
        Retirement.refuseClaimDate(to, claim.getDate());
        reassignment.set(new Reassignment(from, to));
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.Map;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

/** Closes the period, fixing its due-total and each person's due-total in it as they are now: the figures of the claims whose date falls in
 *  it and that count by their status at its end, skipping n/a. Refused when there is no such period or it is already closed. */
public class ClosePeriod {
    public void close(@PathVariable("sheetId") String sheetId, @PathVariable("periodName") String periodName,
            PeriodStore store, RollupService rollups, Out<PeriodResponse> closed) throws InvalidSheetException {
        String sheet = sheetId.trim();
        PeriodResponse period = store.find(sheet, periodName.trim());
        if (period == null) {
            throw new InvalidSheetException("No such period: " + periodName.trim());
        }
        if (period.closed()) {
            throw new InvalidSheetException("The period " + period.name() + " is already closed");
        }
        LocalDate from = LocalDate.parse(period.from());
        LocalDate to = LocalDate.parse(period.to());
        Map<Long, BigDecimal> people = rollups.dueBetweenByPerson(sheet, from, to);
        BigDecimal total = people.values().stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
        if (!store.close(sheet, period.name(), total)) {
            throw new InvalidSheetException("The period " + period.name() + " is already closed");
        }
        store.fixPersonTotals(sheet, period.name(), people);
        closed.set(PeriodResponse.of(period.name(), from, to, true, total, people));
    }
}
package net.officefloor.hq.app.period;

import java.time.LocalDate;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Reopens a closed period, dropping its fixed due-total so it is live again. Refused when the user is
 *  not a steward on the sheet, there is no such period, or it is not closed. */
public class ReopenPeriod {
    public void reopen(@PathVariable("sheetId") String sheetId, @PathVariable("periodName") String periodName,
            @Val CloseRequest request, PeriodStore store, RoleStore roles, Out<PeriodResponse> reopened)
            throws InvalidSheetException {
        String sheet = sheetId.trim();
        if (roles.find(sheet, request.user()) != Role.STEWARD) {
            throw new InvalidSheetException("Only a steward can reopen a period");
        }
        PeriodResponse period = store.find(sheet, periodName.trim());
        if (period == null) {
            throw new InvalidSheetException("No such period: " + periodName.trim());
        }
        if (!period.closed() || !store.reopen(sheet, period.name())) {
            throw new InvalidSheetException("The period " + period.name() + " is not closed");
        }
        reopened.set(PeriodResponse.of(period.name(), LocalDate.parse(period.from()), LocalDate.parse(period.to())));
    }
}

