    private LocalDate policyDate(String sheetId) {
        LocalDate policy = settings.policyDate(sheetId);
        return policy != null ? policy : sheets.today(sheetId);
    }

    /** Only OPEN, PENDING and SETTLED claims count, and an OPEN or PENDING claim dated within one of its
     *  person's holds does not, unless a statement bound it; nor does an OPEN claim deferred on the sheet's today. */
    public static boolean counts(Claim claim, Person person, LocalDate today) {
        return claim.getStatus() == ClaimStatus.SETTLED
                || (claim.getStatus().isOpen() && !claim.isDeferredOn(today)
                        && (claim.isStated() || !person.heldOn(claim.getDate())));
    }

    /** Whether the claim counts by {@code status}, the status it had at a period's end (null when it
     *  was added after it): OPEN, PENDING or SETTLED then; and, as the live rules say, an OPEN claim
     *  deferred on the sheet's today does not, nor one open then dated within a hold of its person,

/** Only OPEN, PENDING and SETTLED claims count toward claimed and the totals; a deferred claim does not. */
export const counts = (c: Claim) => (isOpen(c) && !c.deferred) || c.status === 'SETTLED';

/** Whether the claim keeps the figure (or n/a) its person's last statement bound it to: not while PENDING. */
export const isBound = (c: Claim) => c.stated && (c.statedDue !== null || c.statedNa) && c.status !== 'PENDING';

/** These claims less the OPEN (or PENDING) claims dated within one of their person's holds, which
 *  count in no live total, unless a statement bound them. */
export const live = (claims: Claim[], people: { id: number; holds: Hold[] }[] | undefined) => {
  const holds = new Map((people ?? []).map((p) => [p.id, p.holds]));
  return claims.filter((c) => !(isOpen(c) && !c.stated && (holds.get(c.personId) ?? []).some((h) => covers(h, c.date))));
};

/** Under the sheet's key, so loading the sheet again re-reads its claims. */
export const claimsKey = (sheet: string) => [...sheetKey(sheet), 'claims'] as const;
